    "topic.t1.zh":             { zh: "长上下文语言模型",                  en: "Long-context LLMs" },
    "topic.t1.desc":           { zh: "追踪 LLM 在超长上下文（≥128K）下的注意力机制、记忆压缩、外部记忆模块演进；含 RMT、MemGPT、LongMem、StreamingLLM 等代表方向。",
                                  en: "Tracks attention, memory compression and external-memory work for LLMs at ultra-long context (≥128K), covering RMT, MemGPT, LongMem, StreamingLLM and related directions." },
    "topic.t2.zh":             { zh: "自主智能体工作流",                  en: "Autonomous agent workflows" },
    "topic.t2.desc":           { zh: "覆盖 ReAct、Self-Refine、Reflexion、CRITIC、Tree-of-Thoughts 等 agent 决策范式；含 SWE-Bench、AgentBench 评测追踪。",
                                  en: "Covers ReAct, Self-Refine, Reflexion, CRITIC, Tree-of-Thoughts and other agent-decision paradigms; SWE-Bench and AgentBench tracking included." },
    "topic.t3.zh":             { zh: "AI 模型评测",                       en: "AI model evaluation" },
    "topic.t3.desc":           { zh: "HELM v3、MMLU-Pro、LongBench、BIG-Bench Hard 等评测体系演进；关注 \"helpfulness vs harmlessness\" 维度的设计争论。",
                                  en: "Tracks the evolution of HELM v3, MMLU-Pro, LongBench, BIG-Bench Hard and the «helpfulness vs harmlessness» axis debate." },
    "topic.t4.zh":             { zh: "检索增强 与 记忆系统",              en: "Retrieval-augmented & memory systems" },
    "topic.t4.desc":           { zh: "GraphRAG、Mem0、Zep、Light­RAG 等系统的 episodic/semantic memory 设计；与长上下文路线之争。",
                                  en: "Episodic/semantic memory designs in GraphRAG, Mem0, Zep, LightRAG; the contest with long-context routes." },
    "topic.t5.zh":             { zh: "AI 产品策略",                       en: "AI product strategy" },
    "topic.t5.desc":           { zh: "AI 应用的市场结构、商业化路径、UX 范式；含 a16z、Sequoia、Bessemer 报告与典型案例拆解。",
                                  en: "Market structure, commercialization paths and UX paradigms for AI products; a16z, Sequoia and Bessemer reports plus case dissections." },
    "topic.t6.zh":             { zh: "对齐与安全",                        en: "Alignment & safety" },
    "topic.t6.desc":           { zh: "RLHF、DPO、Constitutional AI、red-teaming 工作；关注模型可解释性进展。",
                                  en: "RLHF, DPO, Constitutional AI, red-teaming work; tracks progress on model interpretability." },
    "topic.t7.zh":             { zh: "多模态与视觉",                      en: "Multimodal & vision" },
    "topic.t7.desc":           { zh: "GPT-4V、Gemini、Pixtral 等多模态模型的视觉推理能力评测。",
                                  en: "Visual-reasoning evaluations of multimodal models like GPT-4V, Gemini and Pixtral." },
    "topic.t8.zh":             { zh: "AI 基础设施",                       en: "AI infrastructure" },
    "topic.t8.desc":           { zh: "vLLM、TGI、SGLang 推理引擎；FlashAttention、PagedAttention 优化技术。",
                                  en: "vLLM, TGI, SGLang inference engines; FlashAttention and PagedAttention optimization." },
    "topic.t9.zh":             { zh: "微调与领域适配",                    en: "Fine-tuning & domain adaptation" },
    "topic.t9.desc":           { zh: "LoRA、QLoRA、P-tuning v2 等参数高效微调；持续学习与灾难性遗忘。",
                                  en: "LoRA, QLoRA, P-tuning v2 parameter-efficient fine-tuning; continual learning and catastrophic forgetting." },
    "topic.t10.zh":            { zh: "开源模型生态",                      en: "Open-source model ecosystem" },
    "topic.t10.desc":          { zh: "Llama、Qwen、DeepSeek、Mistral 等开源模型的能力对比与商业生态。",
                                  en: "Capability comparisons and commercial ecosystems for open models — Llama, Qwen, DeepSeek, Mistral." },
    "topic.t11.zh":            { zh: "推理与数学",                        en: "Reasoning & math" },
    "topic.t11.desc":          { zh: "o1、DeepSeek-R1 类推理模型；Chain-of-Thought 与过程奖励模型 (PRM)。",
                                  en: "o1- and DeepSeek-R1-style reasoning models; Chain-of-Thought and Process Reward Models (PRM)." },
    "topic.t12.zh":            { zh: "语音与实时 AI",                     en: "Voice & real-time AI" },
